values ('full-stack', 'full-stack', 'Full Stack', 'Do banco relacional à interface reativa: construa produtos web ponta a ponta.', 'Unifique front-end, back-end, autenticação e banco de dados em uma trilha de 32 horas focada em entrega real. Ideal para quem quer liderar features completas do requisito ao deploy.', 'web-mobile', 'Intermediário', 2, 32, 30, 189.90, 239.90, null, true, '/images/courses/full-stack.jpg', 'Camadas tridimensionais de vidro fumê e blocos arquitetônicos conectados por luz cobre e esmeralda', ARRAY['TypeScript', 'Next.js', 'Node.js', 'PostgreSQL', 'Supabase'], ARRAY['Arquitetar uma aplicação Full Stack tipada de ponta a ponta com TypeScript', 'Modelar banco PostgreSQL com autenticação, permissões e APIs seguras', 'Colocar uma aplicação completa no ar com observabilidade e CI/CD'], ARRAY['Conhecimento prévio de JavaScript e fundamentos de Front-End'])
