values ('ciberseguranca', 'ciberseguranca', 'Cibersegurança', 'Proteja aplicações web, APIs, credenciais e infraestrutura desde o código.', 'Três cursos essenciais (9h) com foco em segurança defensiva prática (AppSec): vulnerabilidades OWASP Top 10, autenticação segura, gestão de segredos e cultura DevSecOps.', 'dados-cloud', 'Iniciante', 3, 9, 20, 69.90, 89.90, null, false, '/images/courses/ciberseguranca.jpg', 'Escudo blindado em titânio escuro com cadeado luminoso ciano e verde esmeralda ao centro', ARRAY['OWASP Top 10', 'AppSec', 'OAuth2 / JWT', 'Criptografia', 'DevSecOps'], ARRAY['Identificar e corrigir falhas críticas do OWASP Top 10 em aplicações web e APIs', 'Aplicar criptografia correta, armazenamento seguro de senhas e gestão de tokens', 'Integrar verificações automáticas de vulnerabilidades no pipeline de CI'], ARRAY['Conhecimentos básicos de desenvolvimento web e HTTP'])
